/* ---------- quest givers ---------- */
/* at: a spot inside a town (dx,dy from its corner) or a wild spot (nearest open ground in that zone). */
const NPCS={
 marra:{n:'Marra',t:'Cottage keeper',g:'M',room:'th:cottage',place:'Thistledown, the cottage',
  low:'Come back when you have a little more growth on you. The work I have in mind bites.',
  idle:['Stay near the road until you have a companion or two. Press M to see how dangerous each land is for you.','If you ever save up for a skiff, the provisioner sells them. Do not ask me what I think of boats.',"Wipe your feet. It's your pallet, but it's still my floor."]},
 aldous:{n:'Aldous Pennywhistle',t:'Amateur naturalist',g:'A',at:{town:'th',dx:10,dy:4},place:'Thistledown',
  low:'Not yet, my dear fellow. Even Gerald needs to age a little before the great work.',
  idle:['Have I mentioned Gerald? All of them are Gerald. It makes the paperwork so much easier.','I once spent three days in a hedge to watch a jackalope sneeze. Worth every minute. Mostly.']},
 wyn:{n:'Wyn Thistlewick',t:'Hedge-witch',g:'W',at:{town:'th',dx:1,dy:1},place:'Thistledown',
  low:'Not ready for the next batch yet. Grow a little. Like a mushroom, but with fewer regrets.',
  idle:["Magic is mostly knowing which mushrooms won't kill you. I'm not saying it's all of it. I'm saying it's most of it.",'Do not touch the drying racks. The wolfsbane is labeled. The label says "Don\'t."']},
 gruff:{n:'Gruff',t:'Smith',g:'G',at:{town:'cw',dx:10,dy:4},place:'Cragwatch',
  low:'Not yet. Brenda say you small. Brenda is rude. Brenda is right.',
  idle:['(Gruff grunts.) Brenda say hi. Brenda is anvil. Brenda mean it.','Hammer good. Beast bad. Tea... fine.']},
 ysolde:{n:'Captain Ysolde Marrow',t:'Gate captain',g:'Y',at:{town:'cw',dx:1,dy:1},place:'Cragwatch',
  low:'Not yet, recruit. I need people who can survive the briefing, and the briefing is the easy part.',
  idle:["I'm not saying the beasts are winning. I'm saying the morale posters are working overtime.",'Stand up straight. Do not look at the cockatrice. It knows.']},
 hrolf:{n:'Hrolf the Hearthkeeper',t:'Stew enthusiast',g:'H',at:{town:'rh',dx:10,dy:4},place:'Rimehold',
  low:'Another day, friend! The stew is not ready for you, and you are not ready for the stew.',
  idle:['The stew is never finished, only abandoned. Beautiful, is it not?','Winters in Rimehold are long. The stew is longer.']},
 lysandra:{n:'Lysandra Vane',t:'Wardkeeper',g:'L',at:{town:'rh',dx:1,dy:1},place:'Rimehold',
  low:'Not yet. The Wardens turned away people who were ready. You are not even that.',
  idle:['The Wardens of the March kept the passes once. Now we mostly keep the receipts.','Quiet job, this. Quiet because everyone who talks gets assigned something.']},
 slosh:{n:'Old Slosh',t:'Fen hermit',g:'S',at:{wild:'mire',x:60,y:114},place:'Mirelow Fen, west of the lair',
  low:'Squelch. That means come back later. Or move. I never learned which.',
  idle:['Squelch. That is the fen saying hello. Or telling you to move. I never learned the difference.','(He nods gravely at a frog.) Mayor Croak says you look edible. He means it as a compliment.']},
 mcg:{n:'Cinders McGillicuddy',t:'Prospector',g:'C',at:{wild:'cinder',x:140,y:40},place:'Cinder Barrens, near the Frostspine border',
  low:'Not yet, tenderfoot. The ground here is lava, and the lava has opinions.',
  idle:['Forty years prospecting and the gold keeps finding other people. I take it personally.','Careful where you stand. If it glows, it is not a rug.']},
 ozma:{n:'Ozma Plum',t:'Retired relic hunter',g:'O',at:{town:'th',dx:9,dy:4},place:'Thistledown',
  low:'(She whispers.) Not yet. The Aerie does not take applications from the unseasoned. Mr. Tuesday agrees.',
  idle:['(She whispers.) I am seventy-eight years old and I have never lost a relic. Do not check the math.','Mr. Tuesday is my business partner. He has never done any work, but the ideas are all his.']},
 tarquin:{n:'Tarquin Bell',t:'Bell-ringer',g:'T',at:{town:'cw',dx:9,dy:4},place:'Cragwatch',
  low:'WHAT? Oh, not yet. You are not ready. THE BELLS SAY SO. (He is pointing at the wrong bell.)',
  idle:['WHAT? No, I am not shouting. THIS IS MY INDOOR VOICE.','Every problem in the world is a bell problem. I do not make the rules. The bells do.']},
 brynja:{n:'Brynja Brine-Tongue',t:'Storyteller',g:'B',at:{town:'rh',dx:9,dy:4},place:'Rimehold',
  low:'Another winter, friend. The stories wait. They have waited eleven giants already, they will wait one more.',
  idle:['Every legend I tell has exactly one giant too many. It is a signature move.','The true story of Rimehold has at least three giants. I count the ones nobody saw.']},
 embera:{n:'Embera Ash',t:'Fire-warden',g:'E',at:{town:'ew',dx:10,dy:4},place:'Emberwatch',
  low:'Not yet, sparkplug. The Barrens eat the unready, and they are polite about it. They say "mm" and then they eat you.',
  idle:['I have been on fire eleven times this year. Statistically I am still ahead.','Emberwatch is safe. The ground is not. Remember which is which.']},
 saba:{n:'Saba Dune-Kettle',t:'Tea merchant',g:'K',at:{town:'dm',dx:10,dy:4},place:'Dunmarch',
  low:'Not yet, thirsty traveler. First the tea, then the legend, then the invoice.',
  idle:['I sell tea to people dying of thirst. They call it a market. I call it Tuesday.','A good tea is one part water, one part patience, and one part overcharging.']},
 nox:{n:'Nox Wickham',t:'Lamplighter',g:'N',at:{town:'dm',dx:1,dy:1},place:'Dunmarch',
  low:'Not yet. I would offer you a lantern, but I am using all of them, in case of dark.',
  idle:['I am afraid of the dark. It is an awkward trait for a lamplighter, but it makes me thorough.','If the lanterns go out, count to ten and leave. Or leave and count to ten. Both are valid.']}};

